mapper.select:
SELECT COUNT(*) FROM TB_STRUCT_DIAG_HISTORY
WHERE DATA_MODEL_ID = #{dataModelId}
AND STATUS IN ('READY', 'RUNNING')

mapper.insert:
INSERT INTO TB_STRUCT_DIAG_HISTORY (
	DIAG_ID, DATA_MODEL_ID, STATUS, DIAG_DT, CRET_USER_ID
) VALUES (
	#{diagId}, #{dataModelId}, #{status}, CURRENT_TIMESTAMP, #{cretUserId}
)

INSERT INTO TB_STRUCT_DIAG_DETAIL (
	DIAG_ID, SEQ, OWNER, TABLE_NM, COLUMN_NM, CHANGE_TYPE,
	PREV_DATA_TYPE, CURR_DATA_TYPE, PREV_DATA_LEN, CURR_DATA_LEN,
	PREV_NULLABLE, CURR_NULLABLE
) VALUES (
	#{diagId}, #{seq}, #{owner}, #{tableNm}, #{columnNm}, #{changeType},
	#{prevDataType}, #{currDataType}, #{prevDataLen}, #{currDataLen},
	#{prevNullable}, #{currNullable}
)

mapper.select:
SELECT DIAG_ID, DS_ID, DATA_MODEL_ID, SCHEMA_NM, to_char(DIAG_DT, 'YYYY-MM-DD HH24:MI:SS') AS DIAG_DT, STATUS, ADDED_TABLES + ADDED_COLUMNS + MODIFIED_COLUMNS + DELETED_TABLES + DELETED_COLUMNS + ADDED_INDEXES + MODIFIED_INDEXES + DELETED_INDEXES + ADDED_CONSTRAINTS + MODIFIED_CONSTRAINTS + DELETED_CONSTRAINTS AS TOTAL_CHANGES, TOTAL_TABLES, TOTAL_COLUMNS, ADDED_TABLES, ADDED_COLUMNS, MODIFIED_COLUMNS, DELETED_TABLES, DELETED_COLUMNS, CRET_USER_ID FROM TB_STRUCT_DIAG_HISTORY WHERE DS_ID = #{dsId}
AND SCHEMA_NM = #{schemaNm}
ORDER BY DIAG_DT DESC LIMIT 1

mapper.insert:
INSERT INTO TB_STRUCT_DIAG_INDEX_DETAIL (
	DIAG_ID, SEQ, OWNER, TABLE_NM, INDEX_NM, CHANGE_TYPE,
	PREV_INDEX_TYPE, CURR_INDEX_TYPE, PREV_UNIQUENESS, CURR_UNIQUENESS,
	PREV_COLUMNS, CURR_COLUMNS
) VALUES (
	#{diagId}, #{seq}, #{owner}, #{tableNm}, #{indexNm}, #{changeType},
	#{prevIndexType}, #{currIndexType}, #{prevUniqueness}, #{currUniqueness},
	#{prevColumns}, #{currColumns}
)
